// Probes: 14 | Observers: 8 | Tests: 12
// All terminal nodes are observed.

/// Chain test: param_source_std_fermi_fermi_max_lhs -> std.fermi::fermi_eq (depth 4)
/// 
/// Non-tautological: asserts observer matchers, not baseline values.
#[test]
fn test_chain_param_source_std_fermi_fermi_max_lhs_to_std_fermi_fermi_eq() {
    if !guard_test("test_chain_param_source_std_fermi_fermi_max_lhs_to_std_fermi_fermi_eq", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("std/fidelity.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let flat = lower(&dag).expect("lower should succeed").dag;
    let spec = mock_spec();
    // Full baseline DryRun to derive window entry inputs
    let baseline = execute_dag(&flat, ExecuteConfig { mode: ExecutionMode::DryRun(mock_spec().to_boundary_mocks()), ..Default::default() }).expect("baseline DryRun should succeed");
    let window = Window::from_nodes(&flat, vec!("param_source_std_fermi_fermi_gt_lhs", "param_source_std_fermi_fermi_max_lhs", "std.fermi::fermi_eq", "std.fermi::fermi_ordinal"));
    let mut mocks = spec.to_boundary_mocks();
    apply_window_inputs(&flat, &window, &baseline, &mut mocks).expect("chain entry inputs should be derivable from baseline");
    let window_dag = window_subdag(&flat, &window);
    let log = execute_dag(&window_dag, ExecuteConfig { mode: ExecutionMode::DryRun(mocks), ..Default::default() }).expect("chain execution should succeed");

    // Verify observer: std.fermi::fermi_eq (depth 4)
    let mut matchers = HashMap::new();
    for ex in spec.node_examples.iter().filter(|e| e.node_id == "std.fermi::fermi_eq") {
for (port, matcher) in &ex.outputs {
if matcher.is_chain_safe() {
matchers.insert(("std.fermi::fermi_eq".to_string(), port.clone()), matcher.clone());
}
}
}
    for leo in spec.live_expected_outputs.iter().filter(|e| e.node == "std.fermi::fermi_eq") {
if leo.matcher.is_chain_safe() {
matchers.insert(("std.fermi::fermi_eq".to_string(), leo.port.clone()), leo.matcher.clone());
}
}
    assert_chain_outputs(&log, &matchers).expect("chain param_source_std_fermi_fermi_max_lhs -> std.fermi::fermi_eq should satisfy observer matchers");
}

